/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { NEVER, of } from 'rxjs';
import { ActionParamsDialogComponent } from './action-params-dialog.component';
import { ActionParamsDialogService, ActionParamsOptions } from './action-params-dialog.service';

const OPTIONS: ActionParamsOptions = {
  title: 'Cancel',
  message: 'Why?',
  ok: 'Cancel it',
  cancel: 'Back',
  params: [{ name: 'reason', type: 'text', label: 'Reason', required: true }],
};

describe('ActionParamsDialogService', () => {
  let dialog: jasmine.SpyObj<MatDialog>;
  let service: ActionParamsDialogService;

  const closingWith = (value: unknown) => dialog.open.and.returnValue({ afterClosed: () => of(value) } as any);

  beforeEach(() => {
    dialog = jasmine.createSpyObj<MatDialog>('MatDialog', ['open']);
    TestBed.configureTestingModule({ providers: [{ provide: MatDialog, useValue: dialog }] });
    service = TestBed.inject(ActionParamsDialogService);
  });

  it('asks the params in a dialog that does not close by itself', () => {
    closingWith({ reason: 'No budget' });
    let answer: unknown;

    service.ask(OPTIONS).subscribe((value) => (answer = value));

    expect(dialog.open).toHaveBeenCalledWith(ActionParamsDialogComponent, { data: OPTIONS, disableClose: true });
    expect(answer).toEqual({ reason: 'No budget' });
  });

  it('answers null when cancelled', () => {
    closingWith(undefined);
    let answer: unknown = 'not-called';

    service.ask(OPTIONS).subscribe((value) => (answer = value));

    expect(answer).toBeNull();
  });

  it('closes the dialog when unsubscribed before answering', () => {
    const ref = { afterClosed: () => NEVER, close: jasmine.createSpy('close') };
    dialog.open.and.returnValue(ref as any);

    service.ask(OPTIONS).subscribe().unsubscribe();

    expect(ref.close).toHaveBeenCalled();
  });

  it('does not close again a dialog that already answered', () => {
    const ref = { afterClosed: () => of({}), close: jasmine.createSpy('close') };
    dialog.open.and.returnValue(ref as any);

    service.ask(OPTIONS).subscribe().unsubscribe();

    expect(ref.close).not.toHaveBeenCalled();
  });
});
